"""`uv run minimeater-sim`: runs the ngspice checks and writes docs/sim/probe-frontend.md."""

from pathlib import Path

import numpy as np

from ..model.probes import PROBES
from . import budget as Q, fan as FN, frontend as F, ngspice, power as W

TEMPS_F = (32, 150, 225, 325, 500)
TOPOLOGIES = ("as_drawn", "bias_at_tip")


def power_report(out: Path) -> None:
    md = ["# 5 V input in ngspice", "",
          "Generated by `uv run minimeater-sim` (`src/minimeater/sim/power.py`). USB source 5.25 V behind the cable's L and R, "
          "D1 SMF5V0A (6.8 V breakdown, 0.11 ohm), F1 PTC 0.05 ohm (MF-NSMF200-2, 0.02-0.085), then C1 100 uF, C2 and C4 10 uF, 3 x 100 nF "
          "with 3 mohm ESR. `derated` is the MLCC DC-bias loss at 5 V [est]: 45 / 55 / 55 / 90 %. "
          "Absolute maximum at VBUS_F: 6 V on the TLV62569 (SLVSDG1C) and the TLV75533P (VIN), 7 V on the TPS2553 (IN, OUT), all from the datasheets; the 6 V parts set the limit.", "",
          "## Hot plug", "", "| Caps | Cable L | Cable R | Peak at VBUS_F | Peak source current |", "|---|---|---|---|---|"]
    for caps in ("nominal", "derated"):
        for l in (0.25e-6, 1e-6, 2e-6):
            for r in (0.05, 0.1, 0.2):
                h = W.hotplug(W.HotPlug(l, r, caps))
                md.append(f"| {caps} | {l * 1e6:g} uH | {r} ohm | {h['vbus_f_peak']:.2f} V | {h['i_peak']:.0f} A |")
    md += ["", "The PTC (F1, 2 A hold, 0.02-0.085 ohm) and any cable resistance damp the ringing; the TVS (D1, before the PTC) "
           "never conducts. A long, thick cable (2 uH and 0.05-0.1 ohm round trip) with derated caps overshoots VBUS_F "
           "to 6.6-7.2 V, over the 6 V rating of the TLV62569 and TLV75533P for a few microseconds; a normal 1 m cable "
           "(0.5-1 uH, 0.1 ohm and up) stays under 5.9 V. If a scope at bring-up shows more than 6 V with the supply and "
           "cable we use, damp it (an RC snubber or a polymer bulk capacitor on VBUS_F). The current spike is the cost of "
           "100 uF behind a 0.2 ohm path: about 0.9 mC drawn in tens of microseconds, against USB's 50 uC inrush "
           "guideline. A host with a fast over-current trip can see that as a fault; check on a scope at bring-up, and if "
           "ports trip, drop C1 to 22 uF.", "",
           "## Load-switch turn-on (worst case: no slew limit)", "",
           "Switch into the output capacitance at its current limit; 5 V rail behind 0.5 ohm with 130 uF and 0.3 A of other load.", "",
           "| Output | C out | Limit | Rail minimum | Time in limit | Source peak |", "|---|---|---|---|---|---|"]
    for name, c, lim in (("servo (U6, R5 43.2k)", 110e-6, 0.6), ("servo, derated", 52e-6, 0.6), ("fan (U7, R6 49.9k)", 10.2e-6, 0.519)):
        i = W.inrush(c, lim, 0.5, 0.3)
        md.append(f"| {name} | {c * 1e6:.0f} uF | {lim:.2f} A | {i['vin_min']:.2f} V | {i['t_limit'] * 1e3:.2f} ms | {i['i_src_peak']:.2f} A |")
    md += ["", "The rail stays above 4.5 V. The source current is 0.9 A for about a millisecond, "
           "over a Default-class (500 mA) port's limit: firmware should enable the servo only on a 1.5 A or 3 A source, "
           "or while the fan and radio are quiet (ICD: loads are limited by source class).", ""]
    md += ["## 3V3 buck (TLV62569, checked against the datasheet, not simulated)", "",
           "- L1 2.2 uH with 3 x 10 uF at the output is the datasheet's standard LC (Table 4, 10 uF at 2.2 uH, also proven at 22 and 2 x 22 uF); "
           "with the DC-bias loss at 3.3 V (about 55 %) and the -50 % tolerance the effective output capacitance is still above the 10 uF row.",
           "- R3 453k / R4 100k with C7 6.8 pF: 3.32 V, and the 6.8 pF feed-forward is the datasheet's value for R2 = 100k (R2 maximum 200k).",
           "- Switching 1.5 MHz, high-side current limit 3 A, soft start 800 us, UVLO 2.3-2.45 V falling: the servo turn-on above leaves the rail at 4.5 V, far from UVLO.",
           "- A load-step simulation would need a vendor model; measure the 3V3 ripple and a Wi-Fi burst at bring-up.", ""]
    (out / "power.md").write_text("\n".join(md))
    print(out / "power.md")


def budget_report(out: Path) -> None:
    b = Q.B
    md = ["# Probe channel error budget", "",
          "Generated by `uv run minimeater-sim` (`src/minimeater/sim/budget.py`). One channel as on the schematic (47k bias at "
          "the tip, 1k to the ADC pin, 100 nF), every board-side error source at its datasheet limit, the board at "
          f"{Q.T_BOARD:.0f} C. The DC solution is closed form, checked against ngspice to 1e-8 in the ratio. The probe's own "
          "tolerance, lead resistance and a damp probe's leakage are not the board's and are left out "
          "(ADR 0002, `docs/modeling/probes.md`).", "",
          "## Sources and limits", "",
          "| Source | Limit | From |", "|---|---|---|",
          f"| Bias R23 tolerance | +-{b.bias_tol:.2%} | TNPW0603 0.1 % |",
          f"| Bias R23 drift | +-{b.bias_tc:.2%} | 25 ppm/K, 25 to {Q.T_BOARD:.0f} C |",
          f"| ESD leakage at the tip | 0 to {b.esd_leak * 1e9:.0f} nA, to GND | TPD4E05U06 max over temperature (typ 10 pA, ~0.25 nA at 125 C in its Fig 5-5) |",
          f"| ADC absolute input current | +-{b.adc_in * 1e9:.1f} nA | ADS122C04, PGA bypassed: +-5 nA typ, 10 pA/C (no max is published) |",
          f"| R19 tolerance | +-{b.series_tol:.0%} | only with the input current |",
          f"| ADC gain error | +-{b.gain:.3%} | 0.05 % max (gain 1-32) + 2 ppm/C max |",
          f"| ADC offset, after subtraction | +-{b.offset * 1e6:.0f} uV | the firmware subtracts the shorted-input reading every pass [est] |",
          f"| ADC INL | +-{b.inl * 1e6:.0f} uV | 15 ppm of the +-VREF range, max |",
          f"| Noise | +-{b.noise * 1e6:.1f} uV | 3 sigma, interquartile mean of 8 conversions |",
          "| Self-heating | reads high | the probe's dissipation over 1.5 mW/K (still air; far less in meat) |", "",
          "REFP is the same node as the bias resistors' top, so the rail's value, FB2/R18 and the reference input current "
          "(+-10 nA) cancel.", "",
          "## Error against temperature (F)", "",
          "`worst` is every corner of the ranges above plus self-heating; `MC 99.7 %` is the 99.7th percentile of 4000 "
          "Monte Carlo draws (resistors, gain, offset and input current normal with the limit at 3 sigma; ESD leakage and "
          "INL uniform).", "",
          "| Probe | | " + " | ".join(f"{t} F" for t in Q.GRID_F) + " |", "|---|---|" + "---|" * len(Q.GRID_F)]
    for p in PROBES:
        md.append(f"| {p.name} | worst | " + " | ".join(f"{Q.worst_f(p, t):.2f}" for t in Q.GRID_F) + " |")
        md.append(f"| | MC 99.7 % | " + " | ".join(f"{np.percentile(np.abs(Q.monte_carlo_f(p, t)), 99.7):.2f}" for t in Q.GRID_F) + " |")
    acc = Q.accept()
    md += ["", "## Acceptance", "",
           f"- Pit, {Q.PIT_F[0]:.0f}-{Q.PIT_F[1]:.0f} F, every family: worst {acc['pit']:.2f} F (limit 1 F).",
           f"- Food, {Q.FOOD_F[0]:.0f}-{Q.FOOD_F[1]:.0f} F, every family: worst {acc['food']:.2f} F (limit 0.5 F).", "",
           "## Each source alone (F, at its worse end)", "",
           "| Probe | T | " + " | ".join(Q.TERMS + ["self_heating"]) + " |", "|---|---|" + "---|" * (len(Q.TERMS) + 1)]
    for p in PROBES:
        for t in (32, 165, 225, 500):
            tt = Q.terms_f(p, t)
            md.append(f"| {p.name} | {t} F | " + " | ".join(f"{tt[n]:.3f}" for n in Q.TERMS + ["self_heating"]) + " |")
    k = [(cs, Q.kickback(PROBES[2], 225, cs)) for cs in (5e-9 / (Q.F_MOD * Q.VCC), 5e-8 / (Q.F_MOD * Q.VCC))]
    md += ["", "## Sampling kickback (transient)", "",
           "The ADC's input as a switched capacitor at the 256 kHz modulator rate, emptied to AVSS every cycle (the worst "
           "case), on the generic 100k probe at 225 F; the reading is the mean of v(ain) over a 50 ms conversion. "
           "The datasheet gives no sampling capacitance; the first row is the capacitance whose average current is the "
           "spec's 5 nA at full scale, the second ten times that.", "",
           "| C sample | Average current | Per-cycle dip | Reading error | DC current of the same average |", "|---|---|---|---|---|"]
    for cs, r in k:
        md.append(f"| {cs * 1e15:.1f} fF | {r['i_avg'] * 1e9:.2f} nA | {r['dip_v'] * 1e9:.1f} nV | {r['err_f']:+.4f} F | {r['dc_equiv_f']:+.4f} F |")
    md += ["", "The 100 nF node takes each kick without a visible step (the per-cycle charge is fC against 100 nF), and "
           "the reading moves exactly as a DC current of the same average would: the kickback is the datasheet's input "
           "current, already in the budget. Each jack has its own 100 nF, so the mux switching between jacks needs no "
           "settling either; plug-in settling is in `probe-frontend.md`.", "",
           "## Reading it", "",
           "- In the pit and food ranges the bias resistor dominates (tolerance and drift), then the ADC's gain error. "
           "None of it is worth a part change: a 0.05 % or 10 ppm/K resistor would take a tenth of a degree off a budget "
           "that already passes with margin.",
           "- Above 400 F the 100k probes are a few hundred ohms and the ratio is small, so the ADC's INL takes over: up "
           "to about 3 F at 600 F worst case. That is outside the control range (ADR 0002).",
           "- The 1M Maverick at 32 F is 2 F worst case, mostly gain error at a ratio near 1; it is a food-probe ice-bath "
           "check, where the power-up ambient self-check and the per-probe offset trim (ADR 0002) apply.",
           "- The input-current terms (ESD and ADC) together are under 0.05 F in the bands; ADR 0002's 30 nA budget was "
           "conservative. The TPD4E05U06's 10 nA is its max over temperature, so the 'verify at 60 C' item is closed.", ""]
    (out / "probe-budget.md").write_text("\n".join(md))
    print(out / "probe-budget.md")


def fan_report(out: Path) -> None:
    md = ["# Fan PWM and tach in ngspice", "",
          "Generated by `uv run minimeater-sim` (`src/minimeater/sim/fan.py`). The board drives a 5 V 4-wire PWM fan (Noctua "
          "NF-A6x25 5V PWM, placeholder) behind the U7 load switch: GPIO, R28 100R, J6.4 for PWM; J6.3, R27 1k, R16 10k to "
          "3V3 and the pin's 45k pull-up for the tach. The fan's 20 cm lead is lumped: 0.15 uH and 15 pF per conductor "
          "and 8 pF between PWM and tach [est]. The GPIO is 17 ohm (from its IOH/IOL), its pad has clamp diodes, its "
          f"thresholds are VIH {FN.VIH:.2f} V and VIL {FN.VIL:.2f} V; the firmware's PCNT glitch filter drops pulses under "
          f"{FN.PCNT_FILTER_S * 1e6:.1f} us.", "",
          "The bead asked for a low-side MOSFET on a 12 V blower; ADR 0004 replaced that with this fan, which switches its "
          "own motor, so there is no PWM MOSFET and no 12 V tach divider. What is left to check is below.", "",
          "## Tach", "",
          "| Case | Low at the pin | High at the pin (min) | Peak at the pin | Clamp current peak | Rise 10-90 % | Longest glitch past a threshold |",
          "|---|---|---|---|---|---|---|"]
    for name, f in (("as drawn, no pull-up in the fan", FN.Fan()),
                    ("fan with a 10k tach pull-up to 5 V", FN.Fan(tach_pullup=10e3)),
                    ("PWM and tach coupled 30 pF (long lead)", FN.Fan(c_mutual=30e-12))):
        r = FN.tach_report(f)
        md.append(f"| {name} | {r['v_low']:.2f} V | {r['v_high']:.2f} V | {r['v_high_max']:.2f} V | {r['i_clamp_max'] * 1e3:.2f} mA | "
                  f"{r['rise'] * 1e6:.2f} us | {r['glitch_width'] * 1e6:.2f} us |")
    md += ["", "The levels include the PWM's crosstalk: each 25 kHz edge kicks the tach line through the lead (the high "
           "level's minimum and the peak above 3.3 V are those kicks; the pad's clamp takes the upward ones). The low "
           f"stays under VIL ({FN.VIL:.3f} V) by 0.3 V. The downward kick on the high level reaches VIH with 8 pF of "
           "coupling and goes through it with 30 pF, for well under a microsecond: the PCNT filter (12.8 us) drops it, so "
           "the count is safe, but the filter is what makes it safe. The tach is at most 100 Hz (3000 rpm, two pulses "
           "a revolution), so a 1 nF capacitor at the pin (R27 and the pull-ups then filter at about 1-8 us) would "
           "remove the kicks in hardware without slowing the edges that matter; it is not needed with the filter.", "",
           "If the fan has its own tach pull-up to 5 V (Noctua does not publish it), the pin sits at about 4 V through the "
           "pad's clamp, a fraction of a milliamp steady and about 1 mA on the kicks. That is outside the pin's 3.6 V "
           "rating: measure J6.3 with the fan powered and nothing connected at bring-up. If the fan does pull up, the "
           "fix is a divider at the pin sized from the measured value (raising R27 alone would lift the low level past "
           "VIL).", "",
           "## PWM at the fan's input", "",
           "The fan pulls its PWM input up inside (Intel's spec: to at most 5.25 V, sinking at most 5 mA from the "
           "controller, so not below about 1k); the value is not published, so it is swept.", "",
           "| Fan's pull-up to 5 V | Low at the fan (limit 0.8 V) | High at the fan | Overshoot | Current back into the GPIO when high |",
           "|---|---|---|---|---|"]
    for rp in (1e3, 4.7e3, 10e3, 47e3):
        r = FN.pwm_report(FN.Fan(pwm_pullup=rp))
        md.append(f"| {rp / 1e3:g}k | {r['v_low']:.2f} V | {r['v_high']:.2f} V | {r['overshoot']:.2f} V | {r['i_into_gpio'] * 1e3:.2f} mA |")
    ls = FN.load_switch()
    md += ["", "The push-pull GPIO with R28 meets the fan's 0.8 V low even at the strongest pull-up the spec allows. When "
           "the GPIO drives high the fan's pull-up pushes up to 1.5 mA back into it, which the driven pad sinks at 3.3 V. "
           "With the fan off (VFAN down) a high PWM pin would feed the fan through its input; the firmware writes 0 % duty "
           "whenever the fan is off (`tasks.rs`), so the pin is low then.", "",
           "## Load switch U7 (TPS2553, SOT-23)", "",
           f"- Running: the fan's {FN.I_FAN * 1e3:.0f} mA is DC whatever the duty (the fan switches its own motor), so 100 % "
           f"is the worst case: {ls['p_run'] * 1e3:.1f} mW at the 135 mohm maximum, {ls['rise_run']:.1f} C over the board, "
           f"{ls['drop_run'] * 1e3:.0f} mV of drop.",
           f"- Shorted or jammed fan: the switch holds its {FN.I_LIMIT:.2f} A limit with up to {ls['p_short']:.1f} W in it, "
           "and its thermal shutdown (155 C) cycles it; it pulls the shared fault line low, the firmware latches it "
           "(`drive.rs`) and the tach watch raises `fan_stall`.", ""]
    (out / "fan.md").write_text("\n".join(md))
    print(out / "fan.md")


def main() -> None:
    if not ngspice.available():
        raise SystemExit("ngspice not found (brew install ngspice)")
    out = Path("docs/sim")
    out.mkdir(parents=True, exist_ok=True)
    md = ["# Probe front-end in ngspice", "",
          "Generated by `uv run minimeater-sim` (`src/minimeater/sim/frontend.py`). One channel as on the schematic: "
          "jack tip, R19 1k, the ADC node (C29 100 nF, 30 nA leakage), 47k bias to VREF_PROBE (3V3A through FB2, R18, C27, C28). "
          "The firmware converts the ratio assuming a bare 47k bias, as in `minimeater.model.probes`.", "",
          "## Reading error, settled (degF, reading minus truth, 30 nA input current)", "",
          "`as_drawn` is the schematic before the fix (bias on the ADC side of the 1k, so the 1k adds to the probe); "
          "`bias_at_tip` is ADR 0002's order and the schematic now.", "",
          "| Probe | Topology | " + " | ".join(f"{t} F" for t in TEMPS_F) + " |", "|---|---|" + "---|" * len(TEMPS_F)]
    for p in PROBES:
        for top in TOPOLOGIES:
            row = [f"{F.dc_error_f(top, p, t):+.2f}" for t in TEMPS_F]
            md.append(f"| {p.name} | {top} | " + " | ".join(row) + " |")
    md += ["", "## Settling after a probe is plugged in (bias_at_tip)", "",
           "Time for the reading to stay within 0.01 F of its final value, node starting at VREF (empty jack). "
           "The RC is the 47k bias against 100 nF.", "", "| Probe | 32 F | 225 F | 500 F |", "|---|---|---|---|"]
    for p in PROBES:
        row = [f"{F.settle_f('bias_at_tip', p, t)[0] * 1e3:.0f} ms" for t in (32, 225, 500)]
        md.append(f"| {p.name} | " + " | ".join(row) + " |")
    md += ["", "One 20 SPS conversion is 50 ms, so the first reading after a plug-in can still be settling. Firmware should "
           "drop the first conversion after a probe appears (to check against `drivers::ads122c04`).", "",
           "## Ripple on 3V3A", "",
           "Gain from 3V3A to REFP (the filtered VREF_PROBE) and to the ADC pin, 100 k probe (about 25 C), "
           "FB2 modelled as 0.2 ohm + 0.8 uH || 700 ohm [est].", "", "| Frequency | to REFP | to ADC pin |", "|---|---|---|"]
    f = np.array([60, 1e3, 1e4, 1e5, 256e3, 1.5e6])
    _, g = F.rail_ripple_db("bias_at_tip", f, 100e3)
    for fi, (a, b) in zip(f, g):
        md.append(f"| {fi:,.0f} Hz | {a:.1f} dB | {b:.1f} dB |")
    md += ["", f"A 20 mVpp 1.5 MHz buck ripple (assumed) is {20e3 * 10 ** (g[-1, 0] / 20):.0f} uV at REFP. "
           f"The ADS122C04's average input current of 5 nA (datasheet) at its 256 kHz modulator rate is a charge of "
           f"{5e-9 / 256e3 * 1e15:.0f} fC per cycle, {5e-9 / 256e3 / 100e-9 * 1e6:.1f} uV on the 100 nF node.", ""]
    (out / "probe-frontend.md").write_text("\n".join(md))
    print(out / "probe-frontend.md")
    power_report(out)
    budget_report(out)
    fan_report(out)


if __name__ == "__main__":
    main()
